-- =============================================================================
-- April 2026 Funding Deals — batch 2 (29 records)
-- =============================================================================
-- source_name: 'funding_deals_april_2026'  (same batch as phase12/02)
-- Dates are announcement-window midpoints: 2026-04-21 / 04-15 / 04-08.
-- Amounts pre-converted to EUR millions (HrFlow.ai $7M @ 0.92 = 6.44).
-- Novaleum omitted (already in phase12/02). Cobl.ai imported as its own
-- org — flag a later merge with 'thinkeo' (its former name).
-- Existing orgs (Agriodor, Donecle, Aura Aero, Hepta Medical, Hairdex,
-- Luniwave, Mirabelle, Convelio, Decade Energy, Ouidrop) are upserted;
-- the new 2026 round is appended.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS "unaccent";

-- Step 1: Cities (13)
WITH source AS (
  SELECT * FROM json_populate_recordset(NULL::record, $json$[{"name": "Bordeaux"}, {"name": "Clermont-Ferrand"}, {"name": "Ganzeville"}, {"name": "Lille"}, {"name": "Marseille"}, {"name": "Nancy"}, {"name": "Paris"}, {"name": "Rennes"}, {"name": "Suresnes"}, {"name": "Toulouse"}, {"name": "Venansault"}, {"name": "Vitry-sur-Seine"}, {"name": "Épinay-sous-Sénart"}]$json$) AS (name TEXT)
)
INSERT INTO cities (id, name, slug, country, created_at, updated_at)
SELECT uuid_generate_v4(), s.name,
  lower(regexp_replace(regexp_replace(unaccent(s.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g')),
  'France', NOW(), NOW()
FROM source s
ON CONFLICT (slug) DO NOTHING;

-- Step 2: Sectors (23)
WITH source AS (
  SELECT * FROM json_populate_recordset(NULL::record, $json$[{"name": "AgriTech"}, {"name": "Artificial Intelligence"}, {"name": "BioTech"}, {"name": "CleanTech"}, {"name": "ClimateTech"}, {"name": "Cybersecurity"}, {"name": "DeepTech"}, {"name": "DefenseTech"}, {"name": "Drones"}, {"name": "E-commerce & Retail"}, {"name": "Energy"}, {"name": "FinTech"}, {"name": "FoodTech"}, {"name": "Gaming"}, {"name": "HealthTech"}, {"name": "InsurTech"}, {"name": "MarTech"}, {"name": "MedTech"}, {"name": "Mobility"}, {"name": "Robotics"}, {"name": "SaaS"}, {"name": "SpaceTech & Aerospace"}, {"name": "TravelTech"}]$json$) AS (name TEXT)
)
INSERT INTO sectors (id, name, slug, created_at, updated_at)
SELECT uuid_generate_v4(), s.name,
  lower(regexp_replace(regexp_replace(unaccent(s.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g')),
  NOW(), NOW()
FROM source s
ON CONFLICT (slug) DO NOTHING;

-- Step 3: Organizations (upsert by slug; enrich website only)
WITH source AS (
  SELECT * FROM json_populate_recordset(NULL::record, $json$[{"name": "Univity", "website": "https://www.univity.global/", "city": "Paris"}, {"name": "Ouidrop", "website": "https://ouidrop.fr/", "city": "Bordeaux"}, {"name": "Decade Energy", "website": "https://decade.energy/", "city": "Paris"}, {"name": "Bubble Robotics", "website": "https://www.bubble-robotics.com/", "city": "Paris"}, {"name": "Axomove", "website": "https://www.axomove.com/", "city": "Lille"}, {"name": "Five Lives", "website": "https://www.fivelives.health", "city": "Paris"}, {"name": "Sillage", "website": "https://www.getsillage.com/", "city": "Paris"}, {"name": "Biotech One", "website": "https://www.biotech-one.com", "city": "Marseille"}, {"name": "minimiil", "website": "https://minimiil.com/", "city": "Clermont-Ferrand"}, {"name": "Agriodor", "website": "https://www.agriodor.com/", "city": "Rennes"}, {"name": "Donecle", "website": "https://www.donecle.com/", "city": "Toulouse"}, {"name": "HrFlow.ai", "website": "https://www.hrflow.ai/", "city": "Paris"}, {"name": "Mirabelle", "website": "https://www.mirabelle.fr/", "city": "Paris"}, {"name": "Cosmyx", "website": "https://www.cosmyx3d.com/", "city": "Épinay-sous-Sénart"}, {"name": "Cap Atlas", "website": "https://capatlas.fr/", "city": "Ganzeville"}, {"name": "Glimpact", "website": "https://www.glimpact.com/", "city": "Paris"}, {"name": "Proclus", "website": "https://proclus.eco/", "city": "Vitry-sur-Seine"}, {"name": "Hymalaia", "website": "https://www.hymalaia.com/", "city": "Paris"}, {"name": "Oligo+", "website": "https://www.oligoplus.com/", "city": "Nancy"}, {"name": "Convelio", "website": "https://www.convelio.com/", "city": "Paris"}, {"name": "Aura Aero", "website": "https://www.aura-aero.com/", "city": "Toulouse"}, {"name": "NeuroClues", "website": "https://neuroclues.com/", "city": "Paris"}, {"name": "Cobl.ai", "website": "https://www.cobl.ai/", "city": null}, {"name": "Hepta Medical", "website": "https://www.heptamed.com/", "city": "Suresnes"}, {"name": "Luniwave", "website": "https://www.luniwave.com/", "city": "Paris"}, {"name": "Plume", "website": "https://www.plumefinder.com/", "city": null}, {"name": "Playruo", "website": "https://playruo.com/", "city": "Paris"}, {"name": "Hairdex", "website": "https://www.hairdex.fr/", "city": "Marseille"}, {"name": "Easley", "website": "https://easley-impact.com/", "city": "Venansault"}]$json$) AS (name TEXT, website TEXT, city TEXT)
)
INSERT INTO organizations (
  id, name, slug, organization_type, website, status, country, legacy_source, created_at, updated_at
)
SELECT uuid_generate_v4(), s.name,
  lower(regexp_replace(regexp_replace(unaccent(s.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g')),
  'startup'::organization_type, s.website, 'active'::organization_status, 'France',
  'funding_deals_april_2026', NOW(), NOW()
FROM source s
ON CONFLICT (slug) DO UPDATE SET
  website = COALESCE(organizations.website, EXCLUDED.website),
  updated_at = NOW();

-- Step 4: Link organizations to cities (27)
WITH source AS (
  SELECT * FROM json_populate_recordset(NULL::record, $json$[{"org_slug": "univity", "city": "Paris"}, {"org_slug": "ouidrop", "city": "Bordeaux"}, {"org_slug": "decade-energy", "city": "Paris"}, {"org_slug": "bubble-robotics", "city": "Paris"}, {"org_slug": "axomove", "city": "Lille"}, {"org_slug": "five-lives", "city": "Paris"}, {"org_slug": "sillage", "city": "Paris"}, {"org_slug": "biotech-one", "city": "Marseille"}, {"org_slug": "minimiil", "city": "Clermont-Ferrand"}, {"org_slug": "agriodor", "city": "Rennes"}, {"org_slug": "donecle", "city": "Toulouse"}, {"org_slug": "hrflowai", "city": "Paris"}, {"org_slug": "mirabelle", "city": "Paris"}, {"org_slug": "cosmyx", "city": "Épinay-sous-Sénart"}, {"org_slug": "cap-atlas", "city": "Ganzeville"}, {"org_slug": "glimpact", "city": "Paris"}, {"org_slug": "proclus", "city": "Vitry-sur-Seine"}, {"org_slug": "hymalaia", "city": "Paris"}, {"org_slug": "oligo", "city": "Nancy"}, {"org_slug": "convelio", "city": "Paris"}, {"org_slug": "aura-aero", "city": "Toulouse"}, {"org_slug": "neuroclues", "city": "Paris"}, {"org_slug": "hepta-medical", "city": "Suresnes"}, {"org_slug": "luniwave", "city": "Paris"}, {"org_slug": "playruo", "city": "Paris"}, {"org_slug": "hairdex", "city": "Marseille"}, {"org_slug": "easley", "city": "Venansault"}]$json$) AS (org_slug TEXT, city TEXT)
)
UPDATE organizations o
SET city_id = c.id, updated_at = NOW()
FROM source s
JOIN cities c ON c.slug = lower(regexp_replace(regexp_replace(unaccent(s.city), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
WHERE o.slug = s.org_slug AND o.city_id IS NULL;

