  SELECT * FROM json_populate_recordset(NULL::record, $json$[{"org_slug": "univity", "sector": "SpaceTech & Aerospace", "is_primary": true}, {"org_slug": "univity", "sector": "DeepTech", "is_primary": false}, {"org_slug": "ouidrop", "sector": "E-commerce & Retail", "is_primary": true}, {"org_slug": "ouidrop", "sector": "Robotics", "is_primary": false}, {"org_slug": "ouidrop", "sector": "FoodTech", "is_primary": false}, {"org_slug": "decade-energy", "sector": "ClimateTech", "is_primary": true}, {"org_slug": "decade-energy", "sector": "CleanTech", "is_primary": false}, {"org_slug": "decade-energy", "sector": "Energy", "is_primary": false}, {"org_slug": "decade-energy", "sector": "Mobility", "is_primary": false}, {"org_slug": "bubble-robotics", "sector": "Robotics", "is_primary": true}, {"org_slug": "bubble-robotics", "sector": "DefenseTech", "is_primary": false}, {"org_slug": "bubble-robotics", "sector": "ClimateTech", "is_primary": false}, {"org_slug": "bubble-robotics", "sector": "Drones", "is_primary": false}, {"org_slug": "axomove", "sector": "HealthTech", "is_primary": true}, {"org_slug": "axomove", "sector": "MedTech", "is_primary": false}, {"org_slug": "axomove", "sector": "SaaS", "is_primary": false}, {"org_slug": "five-lives", "sector": "HealthTech", "is_primary": true}, {"org_slug": "five-lives", "sector": "Artificial Intelligence", "is_primary": false}, {"org_slug": "sillage", "sector": "Artificial Intelligence", "is_primary": true}, {"org_slug": "sillage", "sector": "SaaS", "is_primary": false}, {"org_slug": "sillage", "sector": "MarTech", "is_primary": false}, {"org_slug": "biotech-one", "sector": "BioTech", "is_primary": true}, {"org_slug": "biotech-one", "sector": "HealthTech", "is_primary": false}, {"org_slug": "biotech-one", "sector": "DeepTech", "is_primary": false}, {"org_slug": "minimiil", "sector": "FoodTech", "is_primary": true}, {"org_slug": "minimiil", "sector": "Artificial Intelligence", "is_primary": false}, {"org_slug": "agriodor", "sector": "AgriTech", "is_primary": true}, {"org_slug": "agriodor", "sector": "ClimateTech", "is_primary": false}, {"org_slug": "agriodor", "sector": "BioTech", "is_primary": false}, {"org_slug": "agriodor", "sector": "FoodTech", "is_primary": false}, {"org_slug": "donecle", "sector": "SpaceTech & Aerospace", "is_primary": true}, {"org_slug": "donecle", "sector": "Artificial Intelligence", "is_primary": false}, {"org_slug": "donecle", "sector": "Robotics", "is_primary": false}, {"org_slug": "donecle", "sector": "Drones", "is_primary": false}, {"org_slug": "hrflowai", "sector": "SaaS", "is_primary": true}, {"org_slug": "hrflowai", "sector": "Artificial Intelligence", "is_primary": false}, {"org_slug": "mirabelle", "sector": "FinTech", "is_primary": true}, {"org_slug": "mirabelle", "sector": "InsurTech", "is_primary": false}, {"org_slug": "cosmyx", "sector": "DeepTech", "is_primary": true}, {"org_slug": "cosmyx", "sector": "DefenseTech", "is_primary": false}, {"org_slug": "cap-atlas", "sector": "Drones", "is_primary": true}, {"org_slug": "cap-atlas", "sector": "SaaS", "is_primary": false}, {"org_slug": "glimpact", "sector": "ClimateTech", "is_primary": true}, {"org_slug": "glimpact", "sector": "SaaS", "is_primary": false}, {"org_slug": "glimpact", "sector": "FoodTech", "is_primary": false}, {"org_slug": "proclus", "sector": "ClimateTech", "is_primary": true}, {"org_slug": "proclus", "sector": "DeepTech", "is_primary": false}, {"org_slug": "hymalaia", "sector": "Artificial Intelligence", "is_primary": true}, {"org_slug": "hymalaia", "sector": "SaaS", "is_primary": false}, {"org_slug": "hymalaia", "sector": "Cybersecurity", "is_primary": false}, {"org_slug": "oligo", "sector": "AgriTech", "is_primary": true}, {"org_slug": "oligo", "sector": "Drones", "is_primary": false}, {"org_slug": "convelio", "sector": "Mobility", "is_primary": true}, {"org_slug": "convelio", "sector": "Artificial Intelligence", "is_primary": false}, {"org_slug": "convelio", "sector": "SaaS", "is_primary": false}, {"org_slug": "aura-aero", "sector": "SpaceTech & Aerospace", "is_primary": true}, {"org_slug": "aura-aero", "sector": "Mobility", "is_primary": false}, {"org_slug": "aura-aero", "sector": "ClimateTech", "is_primary": false}, {"org_slug": "aura-aero", "sector": "DefenseTech", "is_primary": false}, {"org_slug": "neuroclues", "sector": "HealthTech", "is_primary": true}, {"org_slug": "neuroclues", "sector": "MedTech", "is_primary": false}, {"org_slug": "neuroclues", "sector": "Artificial Intelligence", "is_primary": false}, {"org_slug": "coblai", "sector": "Artificial Intelligence", "is_primary": true}, {"org_slug": "coblai", "sector": "SaaS", "is_primary": false}, {"org_slug": "hepta-medical", "sector": "MedTech", "is_primary": true}, {"org_slug": "hepta-medical", "sector": "HealthTech", "is_primary": false}, {"org_slug": "luniwave", "sector": "ClimateTech", "is_primary": true}, {"org_slug": "luniwave", "sector": "TravelTech", "is_primary": false}, {"org_slug": "plume", "sector": "ClimateTech", "is_primary": true}, {"org_slug": "plume", "sector": "Artificial Intelligence", "is_primary": false}, {"org_slug": "playruo", "sector": "Gaming", "is_primary": true}, {"org_slug": "playruo", "sector": "SaaS", "is_primary": false}, {"org_slug": "hairdex", "sector": "HealthTech", "is_primary": true}, {"org_slug": "easley", "sector": "Mobility", "is_primary": true}, {"org_slug": "easley", "sector": "ClimateTech", "is_primary": false}, {"org_slug": "easley", "sector": "SaaS", "is_primary": false}]$json$) AS (org_slug TEXT, sector TEXT, is_primary BOOLEAN)
)
INSERT INTO organization_sectors (id, organization_id, sector_id, is_primary, created_at)
SELECT uuid_generate_v4(), o.id, sec.id,
  CASE WHEN s.is_primary AND NOT EXISTS (SELECT 1 FROM organization_sectors os2 WHERE os2.organization_id = o.id AND os2.is_primary = TRUE) THEN TRUE ELSE FALSE END,
  NOW()
FROM source s
JOIN organizations o ON o.slug = s.org_slug
JOIN sectors sec ON sec.slug = lower(regexp_replace(regexp_replace(unaccent(s.sector), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
WHERE NOT EXISTS (
  SELECT 1 FROM organization_sectors os WHERE os.organization_id = o.id AND os.sector_id = sec.id
);

-- Step 6: Funding rounds (29)
WITH source AS (
  SELECT * FROM json_populate_recordset(NULL::record, $json$[{"org_slug": "univity", "stage": "series_a", "amount_eur": 27.0, "announced_date": "2026-04-21", "notes": "UNIVITY raised €27M to accelerate deployment of its space-based telecom infrastructure (uniShape VLEO 5G demonstrator). 17 LOIs signed; plans a satellite manufacturing facility near Toulouse. (Source: TechEU)"}, {"org_slug": "ouidrop", "stage": "series_a", "amount_eur": 7.0, "announced_date": "2026-04-21", "notes": "Ouidrop raised €7M to industrialize its autonomous 'Dropper' grocery pickup system near Bordeaux (up to 20 units/month), targeting 500 Droppers by 2030. (Source: French Tech Bordeaux)"}, {"org_slug": "decade-energy", "stage": "growth", "amount_eur": 5.0, "announced_date": "2026-04-21", "notes": "Decade Energy raised €22M total (€5.5M equity led by SET Ventures + €16M infra capital from Eiffel) to scale electrification infrastructure for logistics depots across France and into Germany, the Nordics, and Poland. (Source: EU Startups, Eiffel, SET Ventures)"}, {"org_slug": "bubble-robotics", "stage": "seed", "amount_eur": 4.5, "announced_date": "2026-04-21", "notes": "Bubble Robotics raised €4.5M for autonomous ocean data collection (offshore wind, biodiversity, seabed mapping). Testing with Ifremer in Brest; first commercial product next year. (Source: Les Echos)"}, {"org_slug": "axomove", "stage": "series_a", "amount_eur": 4.0, "announced_date": "2026-04-21", "notes": "Axomove raised €4M to scale its reimbursed digital rehabilitation device. Serves 150 B2B clients and 75,000 users; extending reimbursement to musculoskeletal and metabolic conditions. (Source: Les Echos)"}, {"org_slug": "five-lives", "stage": "seed", "amount_eur": 1.9, "announced_date": "2026-04-21", "notes": "Five Lives raised €1.7M (plus crowdfunding up to €2.2M) for its digital therapeutic platform for Alzheimer's prevention, expanding across Europe and the US. (Source: Maddyness, Les Echos)"}, {"org_slug": "sillage", "stage": "pre_seed", "amount_eur": 1.7, "announced_date": "2026-04-21", "notes": "Sillage raised $2M pre-seed at launch to build its sales-signal engine; part of Station F's F/ai accelerator. Early users report >50% higher reply rates. (Source: LinkedIn)"}, {"org_slug": "biotech-one", "stage": "seed", "amount_eur": 1.0, "announced_date": "2026-04-21", "notes": "Biotech One raised €1M to industrialize RNA-into-lipid-nanoparticle encapsulation machines (supercritical CO₂), targeting ~10 machine sales before a €5-10M Series A. (Source: LinkedIn)"}, {"org_slug": "minimiil", "stage": "seed", "amount_eur": 1.0, "announced_date": "2026-04-21", "notes": "minimiil raised €1M to expand in France, launch in the UK, and scale production of its fermented plant-based nutritional shots, using data/AI for supply-chain forecasting. (Source: LinkedIn)"}, {"org_slug": "agriodor", "stage": "series_a", "amount_eur": 15.0, "announced_date": "2026-04-15", "notes": "Agriodor raised €15M to deploy its olfactory (semiochemical) biocontrol technology globally, expanding to additional crops/pests; partners include Syngenta. (Source: World Agritech Innovation)"}, {"org_slug": "donecle", "stage": "growth", "amount_eur": 10.0, "announced_date": "2026-04-15", "notes": "Donecle raised €10M to expand its autonomous drone aircraft-inspection platform across Europe and the US (customers incl. Lufthansa, United, DHL); predictive maintenance software due 2027. (Source: Maddyness, EU Startups)"}, {"org_slug": "hrflowai", "stage": "seed", "amount_eur": 6.44, "announced_date": "2026-04-15", "notes": "HrFlow.ai raised $7M (~€6.44M) to scale its AI HR-data orchestration platform in the US and Europe; has processed 50M+ candidate profiles. Round labeled Pre-Series A. (Source: Maddyness, HrFlow)"}, {"org_slug": "mirabelle", "stage": "seed", "amount_eur": 6.0, "announced_date": "2026-04-15", "notes": "Mirabelle raised €6M and secured ACPR approval as a financing company, launching reverse-mortgage (prêt viager hypothécaire) lending for French seniors. (Source: Finyear)"}, {"org_slug": "cosmyx", "stage": "seed", "amount_eur": 1.3, "announced_date": "2026-04-15", "notes": "Cosmyx raised €1.3M (Paris Business Angels) to accelerate commercial development of its high-speed industrial 3D printers for defense, aerospace, medical, and nuclear; holds defense contracts."}, {"org_slug": "cap-atlas", "stage": "seed", "amount_eur": 0.8, "announced_date": "2026-04-15", "notes": "Cap Atlas raised €1.1M (incl. €300K debt) to develop its drone-based geospatial data and collaborative mapping platform for industrial and surveying use. (Source: Ouest France)"}, {"org_slug": "glimpact", "stage": "seed", "amount_eur": 2.6, "announced_date": "2026-04-15", "notes": "Glimpact raised €2.6M from Sparkalis (Puratos), expanding its science-based environmental-impact measurement platform across food and textiles in Europe and the US. (Source: LinkedIn)"}, {"org_slug": "proclus", "stage": "seed", "amount_eur": 1.0, "announced_date": "2026-04-15", "notes": "Proclus raised €1M to scale reuse of building equipment (circuit breakers, lighting, boilers) from tertiary buildings, addressing 200,000-300,000 tons of annual waste in France. (Source: Les Echos)"}, {"org_slug": "hymalaia", "stage": "seed", "amount_eur": 0.85, "announced_date": "2026-04-15", "notes": "Hymalaia raised $1M to deploy its secure, governed enterprise-AI agent platform aligned with the EU AI Act, for regulated and data-sensitive industries."}, {"org_slug": "oligo", "stage": "pre_seed", "amount_eur": 0.5, "announced_date": "2026-04-15", "notes": "Oligo+ joined the Hexa Sprint program (€500K) to scale its drone-based precision foliar-fertilization model; €1.5M bootstrapped revenue in 2025, targeting €5M by 2026. (Source: LinkedIn)"}, {"org_slug": "convelio", "stage": "series_c", "amount_eur": null, "announced_date": "2026-04-15", "notes": "Convelio secured a Series C (amount undisclosed) to expand its AI-powered fine-art logistics/storage in the $60B art market, launching a New York warehouse; partnered with Phillips. Shipped $1.84B of art in 2025."}, {"org_slug": "aura-aero", "stage": "series_b", "amount_eur": 50.0, "announced_date": "2026-04-08", "notes": "Aura Aero secured €340M total (€50M Series B equity + €120M subsidies + €170M debt) to scale electric/hybrid aircraft production in France and the US; flagship ERA targets entry into service by 2030 (~700 LOIs). (Source: Maddyness)"}, {"org_slug": "neuroclues", "stage": "series_a", "amount_eur": 10.0, "announced_date": "2026-04-08", "notes": "NeuroClues raised €10M Series A to roll out its eye-movement brain-diagnostics device across Europe and into the US. CE-certified, ~30 devices deployed in 7 countries. Franco-Belgian (Brussels/Paris). (Source: Maddyness)"}, {"org_slug": "coblai", "stage": "seed", "amount_eur": 6.0, "announced_date": "2026-04-08", "notes": "Cobl.ai (formerly Thinkeo) raised €6M led by Eurazeo to scale its multi-agent AI platform for sales documents; integrates with Salesforce, Teams, Notion. Clients incl. Orano, Free, Econocom. (Source: Maddyness)"}, {"org_slug": "hepta-medical", "stage": "series_a", "amount_eur": 10.0, "announced_date": "2026-04-08", "notes": "Hepta Medical raised an oversubscribed €10M Series A for its minimally invasive thermal-ablation platform for early-stage lung cancer, funding clinical trials and regulatory milestones. (Source: LinkedIn)"}, {"org_slug": "luniwave", "stage": "seed", "amount_eur": 3.6, "announced_date": "2026-04-08", "notes": "Luniwave raised €3.6M to scale its gamified hotel-sustainability platform (GreenMiles), aiming to equip 800 properties by 2027 (already ~100, incl. Accor, Marriott). (Source: LinkedIn)"}, {"org_slug": "plume", "stage": "seed", "amount_eur": 3.3, "announced_date": "2026-04-08", "notes": "Plume raised €3.3M (led by AENU) for its AI geospatial platform helping renewable developers evaluate solar/wind/battery sites across 150+ data sources; expanding to Italy and the US. (Source: Journal du Net, Maddyness)"}, {"org_slug": "playruo", "stage": "seed", "amount_eur": 2.1, "announced_date": "2026-04-08", "notes": "Playruo raised €2.1M to scale its browser-based cloud gaming platform for studios (playtesting, QA, playable ads). Partners incl. Ubisoft, Webedia, PulluP Entertainment. (Source: Pocket Gamer)"}, {"org_slug": "hairdex", "stage": "seed", "amount_eur": 1.0, "announced_date": "2026-04-08", "notes": "Hairdex, a telehealth platform for male hair loss (androgenetic alopecia), raised €1M. (Source: LinkedIn)"}, {"org_slug": "easley", "stage": "seed", "amount_eur": 0.5, "announced_date": "2026-04-08", "notes": "Easley raised €500K to scale its Oriway EV-mobility SaaS (unified charging access, fleet cost optimization); 15,000+ users, 500,000 charging points across Europe. (Source: LinkedIn)"}]$json$) AS (org_slug TEXT, stage TEXT, amount_eur NUMERIC, announced_date TEXT, notes TEXT)
)
INSERT INTO funding_rounds (
  id, organization_id, stage, amount_eur, currency_original, amount_original,
  announced_date, is_estimated, is_verified, source_name, notes, created_at
)
SELECT uuid_generate_v4(), o.id, s.stage::funding_stage, s.amount_eur, 'EUR',
  s.amount_eur * 1000000, NULLIF(s.announced_date, '')::DATE, FALSE, FALSE,
  'funding_deals_april_2026', s.notes, NOW()
FROM source s
JOIN organizations o ON o.slug = s.org_slug
WHERE NOT EXISTS (
  SELECT 1 FROM funding_rounds fr
  WHERE fr.organization_id = o.id
  AND fr.source_name = 'funding_deals_april_2026'
  AND fr.announced_date IS NOT DISTINCT FROM NULLIF(s.announced_date, '')::DATE
  AND fr.amount_eur IS NOT DISTINCT FROM s.amount_eur
);

